head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.TR_JOB;
scwin.vScrenID = "ULDSTF41521.xml";
scwin.vIsurCd = "";
scwin.vActDD = "";
scwin.vComNm = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_CoSearch.src = "../img/btn_search.gif";
        img_CoSearch.setDisabled(false);
    } else if (initTyp == "X") {
        img_CoSearch.src = "../img/btn_search_d.gif";
        img_CoSearch.setDisabled(true);
        btn_Search.src = "../img/btn_select_d.gif";
        btn_Search.setDisabled(true);
        img_ACT_DD.src = "../img/icn_calendar_d.gif";
        img_ACT_DD.setDisabled(true);
    }
};



/**
 * 증선위조치결과 정보조회
 */
scwin.fn_search_sync = function() {
    var pIsurCd = $c.stf.getObjectValue(txb_ISUR_CD);
    var pComNm = $c.stf.getObjectValue(txb_COM_NM);
    var pActDd = $c.stf.getObjectValue(edt_ACT_DD);
    var url = "/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchSfcActRsltDetail";
    url += "&inputMessageId=SFC_ACT_RSLT_INPUT_OUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&ACT_DD=" + $c.stf.getObjectValue(edt_ACT_DD);
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "" || $c.stf.getObjectValue(edt_ACT_DD) == "") {
        $c.win.alert("[해당회사는 입력 데이터가 없습니다.]");
        dts_Item.insertRow();
        txb_ISUR_CD.setValue(pIsurCd);
        txb_COM_NM.setValue(pComNm);
        edt_ACT_DD.setValue(pActDd);
    }
};
scwin.fn_filedown = function(dtsObj) {
    var vIsurCd = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ISUR_CD");
    var vActDD = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ACT_DD");
    var attach_seq = dtsObj.getCellData(dtsObj.getFocusedRowIndex(), "ATTACH_SEQ");
    location.href = "/filedownload.do?ISUR_CD=" + scwin.vIsurCd + "&ACT_DD=" + scwin.vActDD + "&attach_seq=" + attach_seq + "&gubun=24";
};
scwin.fn_file_read_sync = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SFC_ACT_RSLT_ATTACH_INPUT_OUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstmgt.sfcactrslt.select.attachfile";
    url += "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&{P}param02=" + $c.stf.getObjectValue(edt_ACT_DD);
    dts_File.DataID = encodeURI(url);
    dts_File.Reset();
};
scwin.fn_Dtl_search_sync = function(gubn) {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SFC_ACT_RSLT_DTL_INPUT_OUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstmgt.select.sfcactrslt.dtl.contn.condition";
    url += "&{P}param01=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&{P}param02=" + $c.stf.getObjectValue(edt_ACT_DD);
    url += "&{P}param03=" + gubn;
    if (gubn == "1") {
        dts_List01.DataID = encodeURI(url);
        dts_List01.Reset();
    } else if (gubn == "2") {
        dts_List02.DataID = encodeURI(url);
        dts_List02.Reset();
    } else if (gubn == "3") {
        dts_List03.DataID = encodeURI(url);
        dts_List03.Reset();
    } else if (gubn == "4") {
        dts_List04.DataID = encodeURI(url);
        dts_List04.Reset();
    }
    txa_SFC_ACT_DTL_CONTN.text = "";
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(edt_ACT_DD) == "") {
        $c.win.alert("[조치일]을 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사코드]를 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_AUDTR_NM) == "") {
        $c.win.alert("[감사인]을 입력하세요.");
        return false;
    }
    return true;
};
scwin.fn_setDataItem = function() {
    dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Item.setCellData(1, "ACT_DD", $c.stf.getObjectValue(edt_ACT_DD));
    dts_Item.setCellData(1, "AUDTR_NM", $c.stf.getObjectValue(txb_AUDTR_NM));
    dts_Item.setCellData(1, "REMK", $c.stf.getObjectValue(txa_REMK));
};
scwin.fn_setDataItem02 = function(dts, obj, jobType) {
    if (jobType == TR_JOB_INSERT) {
        dts_Item02.setCellData(1, "SUB_SEQ", "0");
    } else {
        if (eval(obj) > 0) {
            //그리드에서 선택시
            dts_Item02.setCellData(1, "SUB_SEQ", dts.getCellData(eval(obj), "SUB_SEQ"));
        }
    }
    dts_Item02.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Item02.setCellData(1, "ACT_DD", $c.stf.getObjectValue(edt_ACT_DD));
    dts_Item02.setCellData(1, "SFC_DTL_TP_CD", $c.stf.getObjectValue(rdo_PROCS_STAT_CD));
    dts_Item02.setCellData(1, "SFC_ACT_DTL_CONTN", $c.stf.getObjectValue(txa_SFC_ACT_DTL_CONTN));
    if (jobType == TR_JOB_INSERT) {
        LastJob = '저장';
    } else if (jobType == TR_JOB_UPDATE) {
        LastJob = '수정';
    } else if (jobType == TR_JOB_DELETE) {
        LastJob = '삭제';
    }
};



/**
 * 신규입력시 중복입력여부를 체크
 */
scwin.fn_checkDoubleInput = function() {
    var url = "/RepMajagnt.do?method=selectSfcActRsltDoubleCheck&inputMessageId=SFC_ACT_RSLT_DOUBLE_INPUT_OUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&ACT_DD=" + $c.stf.getObjectValue(edt_ACT_DD);
    dts_DoubleChk.DataID = encodeURI(url);
    dts_DoubleChk.Reset();
    var str = dts_DoubleChk.getCellData(1, "DBINPUT_YN");
    if (str == 'Y') {
        $c.win.alert("[해당회사는 이미 동일한 조치일에 입력 데이터가 있습니다.]");
        return false;
    } else if (str == 'N') {
        return true;
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        if ($c.pre_newlisting.fn_checkDoubleInput()) {
            scwin.fn_trs(TR_JOB_INSERT);
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = 'D';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_DELETE);
    }
};
scwin.fn_trs = function(jobType) {
    var vScrenTpCD;
    if (scwin.TR_JOB == 'I') {
        vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    scwin.fn_setDataItem();
    trs_Save.Action = $c.lc.fn_encodeNSession("/RepMajagnt.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenTpCD + "&method=saveSfcActRsltAction");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item,I:pFile1=dts_File)";
    trs_Save.Parameters = "JOB_TYPE=" + jobType;
    trs_Save.Post();
};
scwin.fn_trs02 = function(jobType) {
    if (scwin.fn_CheckForm()) {
        if ($c.stf.getObjectValue(txa_SFC_ACT_DTL_CONTN) == "") {
            $c.win.alert("[내용]을 입력하세요.");
            return false;
        }
        scwin.fn_setDataItem02("", "", jobType);
        trs_Save02.Action = $c.lc.fn_encodeNSession("/RepMajagnt.do?method=saveSfcActRsltDtlAction");
        trs_Save02.KeyName = "toinb_dataid4";
        trs_Save02.KeyValue = "JSP(I:pInput=dts_Item02)";
        trs_Save02.Parameters = "JOB_TYPE=" + jobType;
        trs_Save02.Post();
    }
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_Search;
    fr_fn_list_sync();
};
scwin.rdo_PROCS_STAT_CD_OnSelChange = function() {
    txa_SFC_ACT_DTL_CONTN.text = "";
};
scwin.img_CoSearch_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_search_sync();
};
scwin.btn_Save02_onclick = function() {
    scwin.fn_trs02(TR_JOB_INSERT);
};
scwin.btn_Update02_onclick = function() {
    scwin.fn_trs02(TR_JOB_UPDATE);
};
scwin.btn_Delete02_onclick = function() {
    scwin.fn_trs02(TR_JOB_DELETE);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_ACT_DD_onclick = function() {
    popUpCalendar2(edt_ACT_DD);
};
scwin.dts_DoubleChk_OnLoadError = function() {
    $c.stf.alert_error(dts_DoubleChk);
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        scwin.fn_file_read_sync();
        scwin.fn_Dtl_search_sync("1");
        scwin.fn_Dtl_search_sync("2");
        scwin.fn_Dtl_search_sync("3");
        scwin.fn_Dtl_search_sync("4");
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_initForm("X");
    buttonSet.setUpdateStatus();
    scwin.fn_parentRefresh();
    if (scwin.TR_JOB == "D") {
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search_sync();
    }
};
scwin.trs_Save02_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save02);
};
scwin.trs_Save02_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_Dtl_search_sync($c.stf.getObjectValue(rdo_PROCS_STAT_CD));
    scwin.fn_parentRefresh();
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_File.getTotalRow() == 5) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_File.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        dts_File.setCellData(dts_File.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        $c.cp.removeRow(dts_File, dts_File.getRowPosition());
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_File, dts_File.getRowPosition());
};
scwin.grd_ATTACH_FILE_OnDblClick = function(row, colid) {
    if (row == 0) return;
    if (dts_File.getRowStatus(dts_File.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_File);
    }
};
scwin.grd_List01_OnClick = function(row, colid) {
    if (row == 0) return;
    scwin.fn_setDataItem02(dts_List01, row);
    rdo_PROCS_STAT_CD.setValue("1");
    txa_SFC_ACT_DTL_CONTN.text = dts_List01.getCellData(row, "SFC_ACT_DTL_CONTN");
};
scwin.grd_List02_OnClick = function(row, colid) {
    if (row == 0) return;
    scwin.fn_setDataItem02(dts_List03, row);
    rdo_PROCS_STAT_CD.setValue("3");
    txa_SFC_ACT_DTL_CONTN.text = dts_List03.getCellData(row, "SFC_ACT_DTL_CONTN");
};
scwin.grd_List03_OnClick = function(row, colid) {
    if (row == 0) return;
    scwin.fn_setDataItem02(dts_List02, row);
    rdo_PROCS_STAT_CD.setValue("2");
    txa_SFC_ACT_DTL_CONTN.text = dts_List02.getCellData(row, "SFC_ACT_DTL_CONTN");
};
scwin.grd_List04_OnClick = function(row, colid) {
    if (row == 0) return;
    scwin.fn_setDataItem02(dts_List04, row);
    rdo_PROCS_STAT_CD.setValue("4");
    txa_SFC_ACT_DTL_CONTN.text = dts_List04.getCellData(row, "SFC_ACT_DTL_CONTN");
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.cm.PanelToGroupBox(panel_Body);
    $c.cm.PanelToGroupBox(panel_Item);
    $c.cm.PanelToGroupBox(panel_Dtl);
    //dts_File.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    $c.stf.showObj(file_name, false);
    dts_Item02.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SFC_ACT_RSLT_DTL_INPUT_OUT";
    dts_Item02.reset();
    dts_Item02.insertRow();
    var parentWin = $c.frame.path("../");
    scwin.vIsurCd = parentWin.clickIsurCd;
    scwin.vActDD = parentWin.clickActDD;
    scwin.vComNm = parentWin.clickComNm;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제

    if (scwin.vIsurCd == "" || scwin.vActDD == "") {
        scwin.fn_initForm("C");
        dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SFC_ACT_RSLT_INPUT_OUT";
        dts_Item.reset();
        dts_Item.insertRow();
        txb_ISUR_CD.setValue(scwin.vIsurCd);
        txb_COM_NM.setValue(scwin.vComNm);
    } else {
        txb_ISUR_CD.setValue(scwin.vIsurCd);
        txb_COM_NM.setValue(scwin.vComNm);
        edt_ACT_DD.setValue(scwin.vActDD);
        edt_ACT_DD.setReadOnly(true);
        scwin.fn_initForm("X");
        buttonSet.setUpdateStatus();
        scwin.fn_search_sync();
    }
};
